export async function openVetList(page) {
    await page.getByRole("button", { name: "Veterinarians" }).click();
    await page.getByRole("link", { name: "All" }).click();
    await page.waitForLoadState('networkidle');
}

export async function toggleVetSpecialty(page, vetName, specialtyName) {
    await page.locator("#vets tbody tr").filter({ hasText: vetName }).getByRole("button", { name: "Edit Vet" }).click();
    await page.getByRole("combobox").click();
    await page.getByRole("option", { name: specialtyName }).click();
    await page.keyboard.press("Escape");
    await page.getByRole("button", { name: "Save Vet" }).click();
    await page.waitForLoadState('networkidle');
}
